import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class BeanDeserializerBase_deserializeFromBoolean_TriageGen2Test {

    private JsonParser p;
    private DeserializationContext ctxt;
    private ValueInstantiator instantiator;
    private JsonDeserializer<Object> delegateDeserializer;

    // Since BeanDeserializerBase is abstract and has a protected constructor, 
    // we use a concrete subclass for testing.
    private static class TestBeanDeserializer extends BeanDeserializerBase {
        protected TestBeanDeserializer(BeanDeserializerBuilder builder, BeanDescription beanDesc, BeanPropertyMap properties, 
                                      Map<String, SettableBeanProperty> backRefs, Set<String> ignorableProps, 
                                      boolean ignoreAllUnknown, boolean hasViews) {
            super(builder, beanDesc, properties, backRefs, ignorableProps, ignoreAllUnknown, hasViews);
        }

        @Override
        public JsonDeserializer<Object> unwrappingDeserializer(com.fasterxml.jackson.databind.NameTransformer unwrapper) { return null; }
        @Override
        public BeanDeserializerBase withObjectIdReader(com.fasterxml.jackson.databind.ser.ObjectIdReader oir) { return this; }
        @Override
        public BeanDeserializerBase withIgnorableProperties(java.util.Set<String> ignorableProps) { return this; }
        @Override
        public BeanDeserializerBase withBeanProperties(BeanPropertyMap props) { return this; }
        @Override
        protected BeanDeserializerBase asArrayDeserializer() { return this; }
        @Override
        public void resolve(DeserializationContext ctxt) throws com.fasterxml.jackson.databind.JsonMappingException {}
        @Override
        public JsonDeserializer<?> createContextual(DeserializationContext ctxt, com.fasterxml.jackson.databind.JsonMappingException property) { return null; }
        @Override
        public Object deserializeFromObject(JsonParser p, DeserializationContext ctxt) throws IOException { return null; }
        @Override
        public Object deserializeWithType(JsonParser p, DeserializationContext ctxt, com.fasterxml.jackson.databind.deser.std.TypeDeserializer typeDeserializer) throws IOException { return null; }
        @Override
        protected Object _deserializeUsingPropertyBased(JsonParser p, DeserializationContext ctxt) throws IOException, com.fasterxml.jackson.core.JsonProcessingException { return null; }
        @Override
        public Object deserializeFromString(JsonParser p, DeserializationContext ctxt) throws IOException { return null; }
        @Override
        public Object deserializeFromDouble(JsonParser p, DeserializationContext ctxt) throws IOException { return null; }
        @Override
        public Object deserializeFromArray(JsonParser p, DeserializationContext ctxt) throws IOException { return null; }
        @Override
        public Object deserializeFromEmbedded(JsonParser p, DeserializationContext ctxt) throws IOException { return null; }
    }

    @Before
    public void setUp() {
        p = mock(JsonParser.class);
        ctxt = mock(DeserializationContext.class);
        instantiator = mock(ValueInstantiator.class);
        delegateDeserializer = mock(StdDeserializer.class);
    }

    private TestBeanDeserializer createDeserializer(ValueInstantiator instantiator, JsonDeserializer<Object> delegate, boolean hasInjectables) throws Exception {
        // Use reflection to set protected fields if necessary, but here we mock the behavior via the builder or construction
        // For the purpose of this test, we will use a mock of the base class or a subclass with injected fields via reflection
        TestBeanDeserializer deserializer = mock(TestBeanDeserializer.class, CALLS_REAL_METHODS);

        // Injecting private/protected fields using reflection as they are not accessible via public API
        java.lang.reflect.Field instantiatorField = BeanDeserializerBase.class.getDeclaredField("_valueInstantiator");
        instantiatorField.setAccessible(true);
        instantiatorField.set(deserializer, instantiator);

        java.lang.reflect.Field delegateField = BeanDeserializerBase.class.getDeclaredField("_delegateDeserializer");
        delegateField.setAccessible(true);
        delegateField.set(deserializer, delegate);

        java.lang.reflect.Field injectablesField = BeanDeserializerBase.class.getDeclaredField("_injectables");
        injectablesField.setAccessible(true);
        injectablesField.set(deserializer, hasInjectables ? new java.util.HashSet<com.fasterxml.jackson.databind.deser.InjectableValues>() : null);

        return deserializer;
    }

    @Test
    public void testDeserializeFromBoolean_NoDelegate_True() throws Exception {
        TestBeanDeserializer deserializer = createDeserializer(instantiator, null, false);
        when(p.getCurrentToken()).thenReturn(JsonToken.VALUE_TRUE);
        when(instantiator.createFromBoolean(ctxt, true)).thenReturn("TRUE_OBJECT");

        Object result = deserializer.deserializeFromBoolean(p, ctxt);

        assertEquals("TRUE_OBJECT", result);
        verify(instantiator).createFromBoolean(ctxt, true);
    }

    @Test
    public void testDeserializeFromBoolean_NoDelegate_False() throws Exception {
        TestBeanDeserializer deserializer = createDeserializer(instantiator, null, false);
        when(p.getCurrentToken()).thenReturn(JsonToken.VALUE_FALSE);
        when(instantiator.createFromBoolean(ctxt, false)).thenReturn("FALSE_OBJECT");

        Object result = deserializer.deserializeFromBoolean(p, ctxt);

        assertEquals("FALSE_OBJECT", result);
        verify(instantiator).createFromBoolean(ctxt, false);
    }

    @Test
    public void testDeserializeFromBoolean_WithDelegate_CanCreateFromBooleanFalse() throws Exception {
        TestBeanDeserializer deserializer = createDeserializer(instantiator, delegateDeserializer, false);

        when(instantiator.canCreateFromBoolean()).thenReturn(false);
        when(delegateDeserializer.deserialize(p, ctxt)).thenReturn("DELEGATE_VALUE");
        when(instantiator.createUsingDelegate(ctxt, "DELEGATE_VALUE")).thenReturn("CREATED_BEAN");

        Object result = deserializer.deserializeFromBoolean(p, ctxt);

        assertEquals("CREATED_BEAN", result);
        verify(delegateDeserializer).deserialize(p, ctxt);
        verify(instantiator).createUsingDelegate(ctxt, "DELEGATE_VALUE");
    }

    @Test
    public void testDeserializeFromBoolean_WithDelegate_HasInjectables() throws Exception {
        // Mock injectValues to ensure it's called
        TestBeanDeserializer deserializer = spy(createDeserializer(instantiator, delegateDeserializer, true));

        when(instantiator.canCreateFromBoolean()).thenReturn(false);
        when(delegateDeserializer.deserialize(p, ctxt)).thenReturn("DELEGATE_VALUE");
        when(instantiator.createUsingDelegate(ctxt, "DELEGATE_VALUE")).thenReturn("CREATED_BEAN");

        Object result = deserializer.deserializeFromBoolean(p, ctxt);

        assertEquals("CREATED_BEAN", result);
        // verify injectValues(ctxt, bean) call
        verify(deserializer).injectValues(eq(ctxt), eq("CREATED_BEAN"));
    }

    @Test
    public void testDeserializeFromBoolean_NoDelegate_NullInstantiator() throws Exception {
        // If _delegateDeserializer is null, it skips the first block
        TestBeanDeserializer deserializer = createDeserializer(instantiator, null, false);
        when(p.getCurrentToken()).thenReturn(JsonToken.VALUE_TRUE);
        when(instantiator.createFromBoolean(ctxt, true)).thenReturn("TRUE_OBJECT");

        Object result = deserializer.deserializeFromBoolean(p, ctxt);

        assertEquals("TRUE_OBJECT", result);
    }

    @Test
    public void testDeserializeFromBoolean_WithDelegate_CanCreateFromBooleanTrue() throws Exception {
        // If canCreateFromBoolean is true, it skips the delegate block and goes to createFromBoolean
        TestBeanDeserializer deserializer = createDeserializer(instantiator, delegateDeserializer, false);

        when(instantiator.canCreateFromBoolean()).thenReturn(true);
        when(p.getCurrentToken()).thenReturn(JsonToken.VALUE_TRUE);
        when(instantiator.createFromBoolean(ctxt, true)).thenReturn("DIRECT_BOOLEAN_OBJECT");

        Object result = deserializer.deserializeFromBoolean(p, ctxt);

        assertEquals("DIRECT_BOOLEAN_OBJECT", result);
        verify(delegateDeserializer, never()).deserialize(any(), any());
    }
}
